-- PT115-S4-Q10. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT115-S4-Q10$batch11$ AND q.stimulus=$batch11$The wholesale price of one bottle of Veritas Vineyards wine, always a profitable brand, is the same today as it was in 1991. The winegrower’s profit is equal to the wholesale price minus the costs of producing the bottled wine, which include the cost to the winegrower of the glass bottles themselves and of the corks. Between 1991 and the present, all of the costs to the winegrower of producing a bottle of Veritas Vineyards wine have remained constant, except that of the corks, which cost nearly twice as much today as they did in 1991.$batch11$ AND q.prompt=$batch11$If the statements above are true, which one of the following must also be true on the basis of them?$batch11$ AND q.correct_choice=$batch11$B$batch11$) THEN RAISE EXCEPTION 'Question changed: PT115-S4-Q10'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT115-S4-Q10$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT115-S4-Q10'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT115-S4-Q10$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Profit per bottle equals wholesale price minus production costs. The wholesale price is the same as in 1991. Every cost is the same except corks, which nearly doubled.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Price stays flat, total cost rises because of the corks. Price minus a bigger cost is a smaller number. So each bottle earns less profit now. This is about one bottle, not total sales.$batch11$), (2, $batch11$Goal$batch11$, $batch11$Each bottle sold today earns less profit than each bottle sold in 1991.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT115-S4-Q10$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Sales volume never comes up.$batch11$), ($batch11$B$batch11$, $batch11$Same price minus a higher cost leaves less profit per bottle.$batch11$), ($batch11$C$batch11$, $batch11$The winegrower pays more for corks. That could be the cork maker raising prices, not its own costs rising.$batch11$), ($batch11$D$batch11$, $batch11$Total profit depends on how many bottles were sold. If sales grew enough, total profit could be higher even with thinner margins.$batch11$), ($batch11$E$batch11$, $batch11$Corks doubled in price, but we don't know how they compare with the bottles. A cork could still cost far less than a bottle.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT115-S4-Q10$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
